package mock

import "testing"

func TestHeimdallBenchAssertExpectationsWithNoCalls(t *testing.T) {
	var m Mock
	defer func() {
		if r := recover(); r != nil {
			t.Fatalf("AssertExpectations panicked on a mock with no expectations: %v", r)
		}
	}()
	if !m.AssertExpectations(t) {
		t.Fatal("a mock with no expectations must meet them")
	}
}

